class Solution {
public:
    long long findTheArrayConcVal(std::vector<int>& nums) {
        int i = 0, j = (int)nums.size() - 1;
        long long ans = 0;
        while (i < j) {
            std::string s = std::to_string(nums[i]) + std::to_string(nums[j]);
            ans += std::stoll(s);
            i++;
            j--;
        }
        if (i == j) {
            ans += nums[i];
        }
        return ans;
    }
};

class Solution {
    public long findTheArrayConcVal(int[] nums) {
        int i = 0, j = nums.length - 1;
        long ans = 0;
        while (i < j) {
            String s = String.valueOf(nums[i]) + String.valueOf(nums[j]);
            ans += Long.parseLong(s);
            i++;
            j--;
        }
        if (i == j) {
            ans += nums[i];
        }
        return ans;
    }
}

var findTheArrayConcVal = function(nums) {
    let i = 0, j = nums.length - 1;
    let ans = 0;
    while (i < j) {
        ans += Number(String(nums[i]) + String(nums[j]));
        i++;
        j--;
    }
    if (i === j) {
        ans += nums[i];
    }
    return ans;
};
